
import re
from datetime import date
from pathlib import Path
from typing import Optional

from fastapi import APIRouter, HTTPException, Query
from fastapi.responses import FileResponse


router = APIRouter(
    prefix="/reports/archive",
    tags=["Report Archive"]
)


# Project reports directory
PROJECT_ROOT = Path(__file__).resolve().parents[2]
REPORTS_DIR = PROJECT_ROOT / "reports"

# Only allow filenames generated by our daily report scheduler
REPORT_PATTERN = re.compile(
    r"^Daily_Market_Report_Product_(\d+)_(\d{4}-\d{2}-\d{2})\.pdf$"
)


# --------------------------------------------------
# List Archived Reports
# --------------------------------------------------

@router.get("/")
def list_archived_reports(
    product_id: Optional[int] = Query(default=None, gt=0),
    start_date: Optional[date] = None,
    end_date: Optional[date] = None
):

    if start_date and end_date and start_date > end_date:
        raise HTTPException(
            status_code=400,
            detail="Start date cannot be after end date."
        )

    if not REPORTS_DIR.exists():
        return {
            "total_reports": 0,
            "reports": []
        }

    reports = []

    for file_path in REPORTS_DIR.iterdir():

        if not file_path.is_file():
            continue

        match = REPORT_PATTERN.match(file_path.name)

        if not match:
            continue

        report_product_id = int(match.group(1))
        report_date = date.fromisoformat(match.group(2))

        # Apply product filter
        if product_id is not None:
            if report_product_id != product_id:
                continue

        # Apply date filters
        if start_date and report_date < start_date:
            continue

        if end_date and report_date > end_date:
            continue

        reports.append({
            "filename": file_path.name,
            "product_id": report_product_id,
            "report_date": report_date,
            "file_size_bytes": file_path.stat().st_size,
            "file_size_kb": round(
                file_path.stat().st_size / 1024, 2
            )
        })

    reports.sort(
        key=lambda report: (
            report["report_date"],
            report["product_id"]
        ),
        reverse=True
    )

    return {
        "total_reports": len(reports),
        "reports": reports
    }


# --------------------------------------------------
# Download Archived Report
# --------------------------------------------------

@router.get("/download/{filename}")
def download_archived_report(filename: str):

    if not REPORT_PATTERN.fullmatch(filename):
        raise HTTPException(
            status_code=400,
            detail="Invalid report filename."
        )

    file_path = REPORTS_DIR / filename

    if not file_path.is_file():
        raise HTTPException(
            status_code=404,
            detail="Report not found."
        )

    return FileResponse(
        path=file_path,
        media_type="application/pdf",
        filename=filename
    )
